  ('kazakh-khanate', 'state', 'Казахское ханство', '{"en":"A polity founded in the 15th century that played a central role in the formation of Kazakh statehood.","kk":"XV ғасырда құрылған және қазақ мемлекеттілігінің қалыптасуында шешуші рөл атқарған саяси бірлестік.","ru":"Политическое объединение, возникшее в XV веке и сыгравшее ключевую роль в формировании казахской государственности."}'::jsonb, 1465, 1847, 'medium', 'reviewed', '{"capitals":[{"en":"Suzak","kk":"Созақ","ru":"Сузак"},{"en":"Syganak","kk":"Сығанақ","ru":"Сыгнак"},{"en":"Turkistan","kk":"Түркістан","ru":"Туркестан"}],"datasetVersion":"p2a-2026-08","eventIds":["formation-kazakh-khanate","kasym-khan-consolidation"],"neighbours":[{"en":"Moghulistan","kk":"Моғолстан","ru":"Могулистан"},{"en":"Shaybanid polity","kk":"Шайбанилер мемлекеті","ru":"Государство Шайбанидов"}],"originalEntityType":"state","origins":{"en":"Linked to groups led by Kerei and Janibek leaving Abu’l-Khayr’s polity and settling in Moghulistan.","kk":"Керей мен Жәнібек бастаған тайпалардың Әбілқайыр мемлекетінен бөлініп, Моғолстан аумағына орнығуымен байланысты.","ru":"Связано с уходом части племён во главе с Кереем и Жанибеком из государства Абулхаира и их закреплением в Могулистане."},"people":["kerei-khan","janibek-khan","kasym-khan"],"public":true,"sourceDataset":"src/data/exhibition/entities.js","sourceId":"kazakh-khanate","sourceIds":["e-history-kazakh-khanate","cambridge-kazakh-history","e-history-kasym"],"stages":{"en":"Foundation, consolidation under Kasym Khan, later development and periods of political fragmentation.","kk":"Құрылуы; Қасым хан тұсында нығаюы; кейінгі даму және саяси бытыраңқылық кезеңдері.","ru":"Основание; укрепление при Касым хане; дальнейшее развитие и периоды политической раздробленности."},"statusWasMissing":false}'::jsonb),
