  ('saka-communities', 'archaeological_culture', 'Сакские сообщества', '{"en":"Iron Age groups known from written and archaeological evidence; they were not a single state in the modern sense.","kk":"Жазба деректер мен археологиялық материалдардан белгілі ерте темір дәуірі топтары. Қазіргі түсініктегі біртұтас мемлекет болған жоқ.","ru":"Группы раннего железного века, известные по письменным свидетельствам и археологическим материалам. Не являлись единым государством в современном смысле."}'::jsonb, -800, -300, 'low', 'reviewed', '{"capitals":[],"datasetVersion":"p2a-2026-08","eventIds":["saka-archaeological-record"],"neighbours":[],"originalEntityType":"cultural_political_communities","origins":{"en":"Formed across diverse steppe and foothill environments.","kk":"Дала мен тау бөктерінің әртүрлі ортасында қалыптасты.","ru":"Формировались в разнообразной среде степей и предгорий."},"people":[],"public":true,"sourceDataset":"src/data/exhibition/entities.js","sourceId":"saka-communities","sourceIds":["britannica-kazakhstan-history"],"stages":{"en":"Archaeological cultures differed by region and time.","kk":"Археологиялық мәдениеттер аймақ пен уақытқа қарай ерекшеленді.","ru":"Археологические культуры различались по регионам и времени."},"statusWasMissing":false}'::jsonb),
