insert into public.historical_events (id, titles, descriptions, event_type, start_year, end_year, entity_ids, person_ids, place_ids, source_ids, confidence_level, verification_status, metadata)
values
  ('formation-kazakh-khanate', '{"en":"Formation of the Kazakh Khanate","kk":"Қазақ хандығының құрылуы","ru":"Образование Казахского ханства"}'::jsonb, '{"en":"The conventional chronology places the Khanate’s formation in 1465–1466.","kk":"Дәстүрлі мерзімдеу хандықтың құрылуын 1465–1466 жылдармен байланыстырады.","ru":"Традиционная датировка связывает образование ханства с 1465–1466 годами."}'::jsonb, 'foundation', 1465, 1466, array['kazakh-khanate']::text[], array['kerei-khan', 'janibek-khan']::text[], array['chu-valley']::text[], array['e-history-kazakh-khanate', 'cambridge-kazakh-history']::text[], 'medium', 'needs_review', '{"datasetVersion":"p2a-2026-08","precision":"approximate","public":true,"sourceDataset":"src/data/exhibition/events.js","sourceId":"formation-kazakh-khanate","statusWasMissing":true}'::jsonb),
  ('formation-turkic-khaganate', '{"en":"Formation of the Turkic Khaganate","kk":"Түрік қағанатының құрылуы","ru":"Образование Тюркского каганата"}'::jsonb, '{"en":"Bumin Qaghan’s victory marked the beginning of a new political formation.","kk":"Бумын қағанның жеңісі жаңа саяси бірлестіктің басталуына жол ашты.","ru":"Победа Бумын-кагана стала началом нового политического объединения."}'::jsonb, 'foundation', 552, 552, array['first-turkic-khaganate']::text[], array['bumin-qaghan']::text[], '{}'::text[], array['britannica-turkic-peoples']::text[], 'medium', 'needs_review', '{"datasetVersion":"p2a-2026-08","precision":"year","public":true,"sourceDataset":"src/data/exhibition/events.js","sourceId":"formation-turkic-khaganate","statusWasMissing":true}'::jsonb),
  ('independence-kazakhstan', '{"en":"State independence","kk":"Мемлекеттік тәуелсіздік","ru":"Государственная независимость"}'::jsonb, '{"en":"The Constitutional Law on State Independence was adopted on 16 December.","kk":"16 желтоқсанда мемлекеттік тәуелсіздік туралы Конституциялық заң қабылданды.","ru":"16 декабря принят Конституционный закон о государственной независимости."}'::jsonb, 'foundation', 1991, 1991, array['republic-kazakhstan']::text[], '{}'::text[], array['almaty']::text[], array['adilet-independence-law', 'un-kazakhstan']::text[], 'medium', 'needs_review', '{"datasetVersion":"p2a-2026-08","precision":"day","public":true,"sourceDataset":"src/data/exhibition/events.js","sourceId":"independence-kazakhstan","statusWasMissing":true}'::jsonb),
  ('kasym-khan-consolidation', '{"en":"Consolidation under Kasym Khan","kk":"Қасым хан тұсында хандықтың нығаюы","ru":"Укрепление ханства при Касым хане"}'::jsonb, '{"en":"A period of stronger political influence and wider relations.","kk":"Хандықтың саяси ықпалы мен байланыстары күшейген кезең.","ru":"Период усиления политического влияния и расширения связей ханства."}'::jsonb, 'administrative_reform', 1511, 1521, array['kazakh-khanate']::text[], array['kasym-khan']::text[], array['saraishyk']::text[], array['e-history-kasym', 'cambridge-kazakh-history']::text[], 'medium', 'needs_review', '{"datasetVersion":"p2a-2026-08","precision":"range","public":true,"sourceDataset":"src/data/exhibition/events.js","sourceId":"kasym-khan-consolidation","statusWasMissing":true}'::jsonb),
  ('kazakh-ssr-status', '{"en":"Formation of the Kazakh SSR","kk":"Қазақ КСР-інің құрылуы","ru":"Образование Казахской ССР"}'::jsonb, '{"en":"The Kazakh ASSR was transformed into a union republic.","kk":"Қазақ АКСР-і одақтас республика болып қайта құрылды.","ru":"Казахская АССР была преобразована в союзную республику."}'::jsonb, 'administrative_reform', 1936, 1936, array['kazakh-ssr']::text[], '{}'::text[], array['almaty']::text[], array['britannica-kazakhstan-history']::text[], 'medium', 'needs_review', '{"datasetVersion":"p2a-2026-08","precision":"year","public":true,"sourceDataset":"src/data/exhibition/events.js","sourceId":"kazakh-ssr-status","statusWasMissing":true}'::jsonb),
  ('saka-archaeological-record', '{"en":"Saka archaeological heritage","kk":"Сақтардың археологиялық мұрасы","ru":"Археологическое наследие саков"}'::jsonb, '{"en":"Burial mounds and finds provide evidence about Iron Age societies.","kk":"Қорғандар мен олжалар ерте темір дәуірі қоғамдарын зерттеуге мүмкіндік береді.","ru":"Курганы и находки позволяют изучать общества раннего железного века."}'::jsonb, 'archaeological_discovery', -550, -300, array['saka-communities']::text[], '{}'::text[], array['issyk', 'shilikti']::text[], array['britannica-kazakhstan-history']::text[], 'medium', 'needs_review', '{"datasetVersion":"p2a-2026-08","precision":"approximate","public":true,"sourceDataset":"src/data/exhibition/events.js","sourceId":"saka-archaeological-record","statusWasMissing":true}'::jsonb)
insert into public.historical_people (id, names, descriptions, birth_year, death_year, entity_ids, event_ids, source_ids, confidence_level, verification_status, metadata)
values
  ('bumin-qaghan', '{"en":"Bumin Qaghan","kk":"Бумын қаған","ru":"Бумын-каган"}'::jsonb, '{"en":"Founder of the First Turkic Khaganate.","kk":"Түрік қағанатының негізін қалаушы.","ru":"Основатель Тюркского каганата."}'::jsonb, null, 552, array['first-turkic-khaganate']::text[], array['formation-turkic-khaganate']::text[], array['britannica-turkic-peoples']::text[], 'medium', 'needs_review', '{"datasetVersion":"p2a-2026-08","entityRoles":[{"entityId":"first-turkic-khaganate","role":{"en":"qaghan","kk":"қаған","ru":"каган"}}],"placeIds":[],"portraitUrl":null,"public":true,"sourceDataset":"src/data/exhibition/people.js","sourceId":"bumin-qaghan","statusWasMissing":true}'::jsonb),
  ('janibek-khan', '{"en":"Janibek Khan","kk":"Жәнібек хан","ru":"Жанибек хан"}'::jsonb, '{"en":"A founder of the Kazakh Khanate.","kk":"Қазақ хандығының негізін қалаушылардың бірі.","ru":"Один из основателей Казахского ханства."}'::jsonb, null, null, array['kazakh-khanate']::text[], array['formation-kazakh-khanate']::text[], array['e-history-kazakh-khanate']::text[], 'medium', 'needs_review', '{"datasetVersion":"p2a-2026-08","entityRoles":[{"entityId":"kazakh-khanate","role":{"en":"khan","kk":"хан","ru":"хан"}}],"placeIds":["chu-valley"],"portraitUrl":null,"public":true,"sourceDataset":"src/data/exhibition/people.js","sourceId":"janibek-khan","statusWasMissing":true}'::jsonb),
  ('kasym-khan', '{"en":"Kasym Khan","kk":"Қасым хан","ru":"Касым хан"}'::jsonb, '{"en":"The ruler under whom the Kazakh Khanate significantly consolidated.","kk":"Қазақ хандығы едәуір нығайған кезеңнің билеушісі.","ru":"Правитель, при котором Казахское ханство заметно укрепилось."}'::jsonb, null, 1521, array['kazakh-khanate']::text[], array['kasym-khan-consolidation']::text[], array['e-history-kasym', 'cambridge-kazakh-history']::text[], 'medium', 'needs_review', '{"datasetVersion":"p2a-2026-08","entityRoles":[{"entityId":"kazakh-khanate","role":{"en":"khan","kk":"хан","ru":"хан"}}],"placeIds":["saraishyk"],"portraitUrl":null,"public":true,"sourceDataset":"src/data/exhibition/people.js","sourceId":"kasym-khan","statusWasMissing":true}'::jsonb),
  ('kerei-khan', '{"en":"Kerei Khan","kk":"Керей хан","ru":"Керей хан"}'::jsonb, '{"en":"A founder and the first khan of the Kazakh Khanate.","kk":"Қазақ хандығының негізін қалаушылардың бірі және алғашқы ханы.","ru":"Один из основателей и первый хан Казахского ханства."}'::jsonb, null, null, array['kazakh-khanate']::text[], array['formation-kazakh-khanate']::text[], array['e-history-kazakh-khanate']::text[], 'medium', 'needs_review', '{"datasetVersion":"p2a-2026-08","entityRoles":[{"entityId":"kazakh-khanate","role":{"en":"khan","kk":"хан","ru":"хан"}}],"placeIds":["chu-valley"],"portraitUrl":null,"public":true,"sourceDataset":"src/data/exhibition/people.js","sourceId":"kerei-khan","statusWasMissing":true}'::jsonb)
