  ('adilet-independence-law', '{"en":"Қазақстан Республикасының мемлекеттік тәуелсіздігі туралы","kk":"Қазақстан Республикасының мемлекеттік тәуелсіздігі туралы","ru":"Қазақстан Республикасының мемлекеттік тәуелсіздігі туралы"}'::jsonb, null, '"Әділет — Қазақстан Республикасы нормативтік құқықтық актілерінің ақпараттық-құқықтық жүйесі"'::jsonb, 'Әділет — Қазақстан Республикасы нормативтік құқықтық актілерінің ақпараттық-құқықтық жүйесі', 1991, 'official_portal', 'https://adilet.zan.kz/kaz/docs/Z910004400_', 'unknown', 'verified', '{"citation":"Қазақстан Республикасының 1991 жылғы 16 желтоқсандағы Конституциялық заңы.","datasetVersion":"p2a-2026-08","doi":null,"public":true,"sourceDataset":"src/data/exhibition/sources.js","sourceId":"adilet-independence-law"}'::jsonb),
  ('britannica-kazakhstan-history', '{"en":"Kazakhstan — History","kk":"Kazakhstan — History","ru":"Kazakhstan — History"}'::jsonb, null, '"Encyclopaedia Britannica"'::jsonb, 'Encyclopaedia Britannica', null, 'encyclopedia', 'https://www.britannica.com/place/Kazakhstan/History', 'unknown', 'reviewed', '{"citation":"Encyclopaedia Britannica. Kazakhstan: History.","datasetVersion":"p2a-2026-08","doi":null,"public":true,"sourceDataset":"src/data/exhibition/sources.js","sourceId":"britannica-kazakhstan-history"}'::jsonb),
  ('britannica-turkic-peoples', '{"en":"Turkic peoples","kk":"Turkic peoples","ru":"Turkic peoples"}'::jsonb, null, '"Encyclopaedia Britannica"'::jsonb, 'Encyclopaedia Britannica', null, 'encyclopedia', 'https://www.britannica.com/topic/Turkic-peoples', 'unknown', 'reviewed', '{"citation":"Encyclopaedia Britannica. Turkic peoples.","datasetVersion":"p2a-2026-08","doi":null,"public":true,"sourceDataset":"src/data/exhibition/sources.js","sourceId":"britannica-turkic-peoples"}'::jsonb),
  ('cambridge-kazakh-history', '{"en":"The Cambridge History of Inner Asia: The Chinggisid Age","kk":"The Cambridge History of Inner Asia: The Chinggisid Age","ru":"The Cambridge History of Inner Asia: The Chinggisid Age"}'::jsonb, 'Nicola Di Cosmo, Allen J. Frank, Peter B. Golden (eds.)', '"Cambridge University Press"'::jsonb, 'Cambridge University Press', 2009, 'book', 'https://doi.org/10.1017/CHO9781139056045', 'unknown', 'reviewed', '{"citation":"Di Cosmo, N., Frank, A. J., & Golden, P. B. (eds.). Cambridge University Press, 2009.","datasetVersion":"p2a-2026-08","doi":"10.1017/CHO9781139056045","public":true,"sourceDataset":"src/data/exhibition/sources.js","sourceId":"cambridge-kazakh-history"}'::jsonb),
  ('e-history-kasym', '{"en":"Қасым ханның билігі (1511–1521 жж.)","kk":"Қасым ханның билігі (1511–1521 жж.)","ru":"Қасым ханның билігі (1511–1521 жж.)"}'::jsonb, null, '"Қазақстан тарихы ұлттық порталы"'::jsonb, 'Қазақстан тарихы ұлттық порталы', null, 'official_portal', 'https://e-history.kz/kz/chronology/event/485', 'unknown', 'reviewed', '{"citation":"Қазақстан тарихы ұлттық порталы. Қасым ханның билігі, 1511–1521 жж.","datasetVersion":"p2a-2026-08","doi":null,"public":true,"sourceDataset":"src/data/exhibition/sources.js","sourceId":"e-history-kasym"}'::jsonb),
  ('e-history-kazakh-khanate', '{"en":"Қазақ хандығы (1465–1466 жж.)","kk":"Қазақ хандығы (1465–1466 жж.)","ru":"Қазақ хандығы (1465–1466 жж.)"}'::jsonb, 'Б. Б. Кәрібаев', '"Қазақстан тарихы ұлттық порталы"'::jsonb, 'Қазақстан тарихы ұлттық порталы', null, 'official_portal', 'https://e-history.kz/kz/chronology/event/116', 'unknown', 'reviewed', '{"citation":"Кәрібаев Б. Б. Қазақ хандығы (1465–1466 жж.). Қазақстан тарихы ұлттық порталы.","datasetVersion":"p2a-2026-08","doi":null,"public":true,"sourceDataset":"src/data/exhibition/sources.js","sourceId":"e-history-kazakh-khanate"}'::jsonb),
  ('qhm-p1c-educational-overlay', '{"en":"Qazaq Heritage Map P1C educational evidence overlay","kk":"Qazaq Heritage Map P1C educational evidence overlay","ru":"Qazaq Heritage Map P1C educational evidence overlay"}'::jsonb, 'Qazaq Heritage Map editorial team', '"Qazaq Heritage Map"'::jsonb, 'Qazaq Heritage Map', 2026, 'educational_reconstruction', '/exhibition', 'permission_granted', 'reviewed', '{"citation":"Qazaq Heritage Map. P1C educational evidence overlay. Original educational reconstruction, 2026.","datasetVersion":"p2a-2026-08","doi":null,"public":true,"sourceDataset":"src/data/exhibition/sources.js","sourceId":"qhm-p1c-educational-overlay"}'::jsonb),
