insert into public.source_claims (id, subject_type, subject_id, predicate, value_type, claim_value, labels, evidence_type, confidence_level, verification_status, interpretation_notes, reviewed_by, reviewed_at, metadata)
values
  ('claim-change-1511-1521', 'historical_change', 'kazakh-khanate-1511-to-1521', 'territorial_extent', 'comparison', '{"conclusion":"displayed_outlines_differ","fromYear":1511,"toYear":1521}'::jsonb, '{"en":"The displayed 1511 and 1521 outlines differ, but the difference does not prove exact border dynamics","kk":"1511 және 1521 жылдардағы контурлар өзгеше, бірақ айырмашылық шекаралардың нақты динамикасын дәлелдемейді","ru":"Отображаемые контуры 1511 и 1521 годов различаются, но разница не доказывает точную динамику границ"}'::jsonb, 'academic_interpretation', 'low', 'needs_review', '{"en":"The geometric difference is an object of analysis, not independent evidence.","kk":"Геометриялық айырмашылық дербес дереккөз емес, талдау нысаны.","ru":"Геометрическая разница служит объектом анализа, а не самостоятельным источником."}'::jsonb, null, null, '{"datasetVersion":"p2a-2026-08","public":true,"sourceDataset":"src/data/exhibition/sourceClaims.js","sourceId":"claim-change-1511-1521"}'::jsonb),
  ('claim-independence-1991', 'event', 'independence-kazakhstan', 'event_date', 'date', '{"day":16,"month":12,"year":1991}'::jsonb, '{"en":"The Constitutional Law on State Independence was adopted on 16 December 1991","kk":"Мемлекеттік тәуелсіздік туралы Конституциялық заң 1991 жылғы 16 желтоқсанда қабылданды","ru":"Конституционный закон о государственной независимости принят 16 декабря 1991 года"}'::jsonb, 'official_document', 'high', 'verified', '{"en":"The claim concerns the date of the official legal act.","kk":"Тұжырым ресми құқықтық актінің күніне қатысты.","ru":"Утверждение относится к дате официального правового акта."}'::jsonb, null, null, '{"datasetVersion":"p2a-2026-08","public":true,"sourceDataset":"src/data/exhibition/sourceClaims.js","sourceId":"claim-independence-1991"}'::jsonb),
  ('claim-khanate-1465-territory', 'geometry', 'khanate-1465', 'territorial_extent', 'geometry_reference', '{"geometryId":"khanate-1465","represents":"interpretive_extent"}'::jsonb, '{"en":"The 1465 outline represents an interpretive extent, not an exact state border","kk":"1465 жылғы контур нақты мемлекеттік шекараны емес, түсіндірмелік қамтуды көрсетеді","ru":"Контур 1465 года показывает интерпретируемый охват, а не точную государственную границу"}'::jsonb, 'educational_reconstruction', 'low', 'needs_review', '{"en":"The sources provide historical context but do not validate every polygon vertex.","kk":"Дереккөздер тарихи контекст береді, бірақ полигонның әр төбесін растамайды.","ru":"Источники дают исторический контекст, но не подтверждают каждую вершину полигона."}'::jsonb, null, null, '{"datasetVersion":"p2a-2026-08","public":true,"sourceDataset":"src/data/exhibition/sourceClaims.js","sourceId":"claim-khanate-1465-territory"}'::jsonb),
  ('claim-khanate-foundation-1465', 'entity', 'kazakh-khanate', 'foundation_period', 'year_range', '{"endYear":1466,"startYear":1465}'::jsonb, '{"en":"The formation of the Kazakh Khanate is conventionally dated to approximately 1465–1466","kk":"Қазақ хандығының құрылуы дәстүрлі түрде шамамен 1465–1466 жылдармен белгіленеді","ru":"Формирование Казахского ханства традиционно датируют приблизительно 1465–1466 годами"}'::jsonb, 'academic_interpretation', 'high', 'reviewed', '{"en":"This is a conventional chronology for a formation period, not proof of one exact day.","kk":"Бұл бір нақты күннің дәлелі емес, қалыптасу кезеңінің дәстүрлі мерзімдемесі.","ru":"Это традиционная датировка периода формирования, а не доказательство одного точного дня."}'::jsonb, null, null, '{"datasetVersion":"p2a-2026-08","public":true,"sourceDataset":"src/data/exhibition/sourceClaims.js","sourceId":"claim-khanate-foundation-1465"}'::jsonb),
  ('claim-otrar-location', 'place', 'otrar', 'place_location', 'coordinates', '{"coordinates":[68.3,42.85],"precision":"approximate"}'::jsonb, '{"en":"Otrar is shown with an approximate point for the historical centre","kk":"Отырар тарихи орталықтың шамамен алынған нүктесімен көрсетілген","ru":"Отырар показан приблизительной точкой исторического центра"}'::jsonb, 'educational_reconstruction', 'low', 'needs_review', '{"en":"The point supports navigation and does not define the archaeological complex boundary.","kk":"Нүкте навигацияға арналған және археологиялық кешеннің шекарасын белгілемейді.","ru":"Точка предназначена для навигации и не задаёт границы археологического комплекса."}'::jsonb, null, null, '{"datasetVersion":"p2a-2026-08","public":true,"sourceDataset":"src/data/exhibition/sourceClaims.js","sourceId":"claim-otrar-location"}'::jsonb),
  ('claim-overlay-educational', 'story', 'historical-evidence', 'relationship', 'archive_map_reference', '{"archiveMapId":"qhm-evidence-overlay-demo"}'::jsonb, '{"en":"The demonstration map was created by the project for source-analysis education and is not an archival original","kk":"Демонстрациялық картаны жоба дереккөздерді талдауды үйрету үшін жасаған және ол архивтік түпнұсқа емес","ru":"Демонстрационная карта создана проектом для обучения анализу источников и не является архивным оригиналом"}'::jsonb, 'educational_reconstruction', 'high', 'reviewed', '{"en":"Alignment with the reconstruction does not prove historical border accuracy.","kk":"Схеманың реконструкциямен сәйкес келуі тарихи шекаралардың дәлдігін дәлелдемейді.","ru":"Совпадение схемы с реконструкцией не доказывает точность исторических границ."}'::jsonb, null, null, '{"datasetVersion":"p2a-2026-08","public":true,"sourceDataset":"src/data/exhibition/sourceClaims.js","sourceId":"claim-overlay-educational"}'::jsonb),
  ('claim-silk-road-direction', 'route', 'silk-road-southern-kazakhstan', 'route_direction', 'route_reference', '{"routeId":"silk-road-southern-kazakhstan","status":"reconstructed_direction"}'::jsonb, '{"en":"The line shows a reconstructed Southern Kazakhstan direction of the Silk Road","kk":"Сызық Жібек жолының Оңтүстік Қазақстандағы реконструкцияланған бағытын көрсетеді","ru":"Линия показывает реконструированное южноказахстанское направление Шёлкового пути"}'::jsonb, 'educational_reconstruction', 'medium', 'needs_review', '{"en":"This is a generalized direction between cities, not a recorded exact track.","kk":"Бұл қалалар арасындағы жалпыланған бағыт, нақты жазылған трек емес.","ru":"Это обобщённое направление между городами, а не записанный точный трек."}'::jsonb, null, null, '{"datasetVersion":"p2a-2026-08","public":true,"sourceDataset":"src/data/exhibition/sourceClaims.js","sourceId":"claim-silk-road-direction"}'::jsonb),
  ('claim-steppe-demo-status', 'environment', 'southern-steppe-medieval-demo', 'environmental_state', 'status', '{"status":"educational_reconstruction"}'::jsonb, '{"en":"The environment zone is an educational diagram requiring scholarly review","kk":"Табиғи аймақ — ғылыми тексеруді қажет ететін оқу схемасы","ru":"Природная зона является образовательной схемой и требует научной проверки"}'::jsonb, 'educational_reconstruction', 'low', 'needs_review', '{"en":"The diagram is not a detailed palaeoclimate reconstruction.","kk":"Схема егжей-тегжейлі палеоклиматтық реконструкция емес.","ru":"Схема не является детальной палеоклиматической реконструкцией."}'::jsonb, null, null, '{"datasetVersion":"p2a-2026-08","public":true,"sourceDataset":"src/data/exhibition/sourceClaims.js","sourceId":"claim-steppe-demo-status"}'::jsonb)
