  ('syr-darya-valley-medieval-demo', 'river_valley', '{"en":"Syr Darya valley","kk":"Сырдария аңғары","ru":"Долина Сырдарьи"}'::jsonb, '{"en":"An interpretive river-valley band for educational comparison of cities and routes.","kk":"Қалалар мен бағыттарды оқу мақсатында салыстыруға арналған шартты өзен аңғары.","ru":"Условная полоса речной долины для образовательного сопоставления городов и маршрутов."}'::jsonb, extensions.st_setsrid(extensions.st_geomfromgeojson('{"coordinates":[[[61,41.2],[69.5,42],[72,43],[70.5,44],[62,42.7],[61,41.2]]],"type":"Polygon"}'), 4326), 700, 1500, false, array['unesco-silk-roads']::text[], 'low', 'needs_review', '{"datasetVersion":"p2a-2026-08","public":true,"screenReaderDescriptions":{"en":"An interpretive river valley runs northwest from the southeast toward the Aral region.","kk":"Шартты өзен аңғары оңтүстік-шығыстан Арал теңізі аймағына қарай өтеді.","ru":"Условная речная долина проходит с юго-востока к району Аральского моря."},"sourceDataset":"src/data/exhibition/environmentSnapshots.js","sourceId":"syr-darya-valley-medieval-demo"}'::jsonb),
  ('tian-shan-foothills-medieval-demo', 'mountain', '{"en":"Tian Shan foothills","kk":"Тянь-Шань тау бөктері","ru":"Предгорья Тянь-Шаня"}'::jsonb, '{"en":"A generalized mountain and foothill zone used to explain the geographic context of cities.","kk":"Қалалардың географиялық мәнмәтінін түсіндіруге арналған таулар мен тау бөктерінің жалпыланған аймағы.","ru":"Обобщённая зона гор и предгорий для объяснения географического контекста городов."}'::jsonb, extensions.st_setsrid(extensions.st_geomfromgeojson('{"coordinates":[[[68,39.5],[81,39.5],[80,44],[70,43.5],[68,39.5]]],"type":"Polygon"}'), 4326), 500, 1500, false, array['unesco-silk-roads']::text[], 'low', 'demo_only', '{"datasetVersion":"p2a-2026-08","public":true,"screenReaderDescriptions":{"en":"A demonstration foothill zone runs along the southern edge of the educational map.","kk":"Демонстрациялық тау бөктері аймағы оқу картасының оңтүстік шекарасы бойында орналасқан.","ru":"Демонстрационная зона предгорий расположена вдоль южной границы учебной карты."},"sourceDataset":"src/data/exhibition/environmentSnapshots.js","sourceId":"tian-shan-foothills-medieval-demo"}'::jsonb)
