insert into public.educational_stories (id, titles, descriptions, target_audience, duration_minutes, verification_status, metadata)
values
  ('formation-and-consolidation-kazakh-khanate', '{"en":"Formation and consolidation of the Kazakh Khanate","kk":"Қазақ хандығының қалыптасуы мен нығаюы","ru":"Формирование и укрепление Казахского ханства"}'::jsonb, '{"en":"A ten-step story about events, people, reconstructions and sources in the 15th–16th centuries.","kk":"XV–XVI ғасырлардағы оқиғалар, тұлғалар, реконструкциялар мен дереккөздер туралы он қадамдық тарих.","ru":"Десятишаговая история о событиях, людях, реконструкциях и источниках XV–XVI веков."}'::jsonb, 'grade-7', 10, 'reviewed', '{"datasetVersion":"p2a-2026-08","public":true,"questionIds":["reconstruction-boundaries","compare-1465-1511","formation-sources","kasym-person"],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"formation-and-consolidation-kazakh-khanate"}'::jsonb),
  ('historical-evidence', '{"en":"How historians reconstruct a map of the past","kk":"Тарихшылар өткеннің картасын қалай қалпына келтіреді","ru":"Как историки восстанавливают карту прошлого"}'::jsonb, '{"en":"A nine-step lesson about claims, sources, reconstructions, rights, and scholarly review.","kk":"Claims, дереккөздер, реконструкциялар, құқықтар және ғылыми тексеру туралы тоғыз қадамдық сабақ.","ru":"Девятишаговый урок о claims, источниках, реконструкциях, правах и научной проверке."}'::jsonb, 'grade-8-11', 10, 'reviewed', '{"datasetVersion":"p2a-2026-08","public":true,"questionIds":["evidence-fact-interpretation","evidence-boundary-versions","evidence-archaeological-place","evidence-map-alignment","evidence-publication-check"],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"historical-evidence"}'::jsonb),
  ('silk-road-geography', '{"en":"How geography shaped the cities of the Silk Road","kk":"География Ұлы Жібек жолы қалаларының дамуына қалай әсер етті","ru":"Как география влияла на развитие городов Великого Шёлкового пути"}'::jsonb, '{"en":"An eight-step story about environment, cities, and a reconstructed route direction.","kk":"Табиғи орта, қалалар және реконструкцияланған бағыт туралы сегіз қадамдық тарих.","ru":"Восьмишаговая история о природной среде, городах и реконструированном направлении маршрута."}'::jsonb, 'grade-7-8', 10, 'needs_review', '{"datasetVersion":"p2a-2026-08","public":true,"questionIds":["geography-river-cities","geography-caravan-conditions","geography-cultural-links","geography-route-reconstruction"],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"silk-road-geography"}'::jsonb)
insert into public.educational_story_steps (id, story_id, step_order, year, era_id, camera, titles, narration, simple_narration, source_ids, metadata)
values
  ('formation-and-consolidation-kazakh-khanate:compare-1465-and-1511', 'formation-and-consolidation-kazakh-khanate', 6, 1511, 'kazakh-khanate', '{"bearing":0,"center":[68,47],"pitch":24,"zoom":3.9}'::jsonb, '{"en":"Comparing 1465 and 1511","kk":"1465 және 1511 жылдарды салыстыру","ru":"Сравнение 1465 и 1511 годов"}'::jsonb, '{"en":"The overlay shows a broader visual extent in the second reconstruction. Geometric difference does not create a new historical cause.","kk":"Қабаттасу екінші реконструкцияның көрнекі қамтуы үлкен екенін көрсетеді. Геометриялық айырма жаңа тарихи себеп жасамайды.","ru":"Наложение показывает больший визуальный охват второй реконструкции. Геометрическая разница не создаёт новую историческую причину."}'::jsonb, '{"en":"The second reconstruction is visually broader.","kk":"Екінші реконструкция біріншісінен көрнекі түрде кең.","ru":"Вторая реконструкция визуально шире первой."}'::jsonb, array['e-history-kazakh-khanate', 'e-history-kasym', 'cambridge-kazakh-history']::text[], '{"action":{"fromYear":1465,"toYear":1511,"type":"comparison"},"activeLayers":["comparison"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":["formation-kazakh-khanate","kasym-khan-consolidation"],"personIds":["kerei-khan","janibek-khan","kasym-khan"],"placeIds":["chu-valley","saraishyk"],"public":true,"questionId":"compare-1465-1511","sourceClaims":[{"claimsSupported":{"en":"Kasym Khan’s reign","kk":"Қасым хан билігінің кезеңі","ru":"Период правления Касым хана"},"sourceId":"e-history-kasym"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"compare-1465-and-1511","storyId":"formation-and-consolidation-kazakh-khanate"}'::jsonb),
  ('formation-and-consolidation-kazakh-khanate:early-khanate-territory', 'formation-and-consolidation-kazakh-khanate', 4, 1465, 'kazakh-khanate', '{"bearing":0,"center":[69,46],"pitch":34,"zoom":4.45}'::jsonb, '{"en":"Territory of the early Khanate","kk":"Ерте хандықтың аумағы","ru":"Территория раннего ханства"}'::jsonb, '{"en":"The 1465 outline is an educational reconstruction of the early Khanate’s extent, not an exact official border.","kk":"1465 жылғы контур ерте хандықтың қамтуының оқу реконструкциясын көрсетеді. Ол дәл ресми шекара емес.","ru":"Контур 1465 года показывает учебную реконструкцию охвата раннего ханства. Он не является точной официальной границей."}'::jsonb, '{"en":"The outline supports comparison but remains approximate.","kk":"Контур кезеңдерді салыстыруға көмектеседі, бірақ шамамен берілген.","ru":"Контур помогает сравнивать периоды, но остаётся приблизительным."}'::jsonb, array['e-history-kazakh-khanate', 'cambridge-kazakh-history']::text[], '{"action":null,"activeLayers":["territories","labels"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":["formation-kazakh-khanate"],"personIds":[],"placeIds":["chu-valley","turkistan"],"public":true,"questionId":"reconstruction-boundaries","sourceClaims":[{"claimsSupported":{"en":"Academic context for the reconstruction","kk":"Реконструкцияның академиялық мәнмәтіні","ru":"Академический контекст реконструкции"},"sourceId":"cambridge-kazakh-history"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"early-khanate-territory","storyId":"formation-and-consolidation-kazakh-khanate"}'::jsonb),
  ('formation-and-consolidation-kazakh-khanate:formation-1465-1466', 'formation-and-consolidation-kazakh-khanate', 3, 1465, 'kazakh-khanate', '{"bearing":-8,"center":[69.3,45.4],"pitch":38,"zoom":4.6}'::jsonb, '{"en":"Formation of the Khanate in 1465–1466","kk":"Хандықтың 1465–1466 жылдары құрылуы","ru":"Образование ханства в 1465–1466 годах"}'::jsonb, '{"en":"1465–1466 is used as a conventional scholarly chronology, not an undisputed point with an exact cartographic border.","kk":"1465–1466 жылдар дәл картографиялық шекарасы бар даусыз нүкте емес, қабылданған ғылыми мерзім ретінде қолданылады.","ru":"1465–1466 годы используются как принятая научная датировка, а не как бесспорная точка с точной картографической границей."}'::jsonb, '{"en":"Historians commonly date the formation to 1465–1466.","kk":"Тарихшылар хандықтың құрылуын көбіне 1465–1466 жылдармен белгілейді.","ru":"Историки часто датируют образование ханства 1465–1466 годами."}'::jsonb, array['e-history-kazakh-khanate', 'cambridge-kazakh-history']::text[], '{"action":null,"activeLayers":["territories","events","places"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":["formation-kazakh-khanate"],"personIds":["kerei-khan","janibek-khan"],"placeIds":["chu-valley"],"public":true,"questionId":"formation-sources","sourceClaims":[{"claimsSupported":{"en":"Conventional chronology of the Khanate’s formation","kk":"Хандықтың құрылуының қабылданған мерзімі","ru":"Принятая датировка образования ханства"},"sourceId":"e-history-kazakh-khanate"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"formation-1465-1466","storyId":"formation-and-consolidation-kazakh-khanate"}'::jsonb),
  ('formation-and-consolidation-kazakh-khanate:kasym-khan', 'formation-and-consolidation-kazakh-khanate', 5, 1511, 'kazakh-khanate', '{"bearing":3,"center":[66.5,48.3],"pitch":34,"zoom":4}'::jsonb, '{"en":"Kasym Khan","kk":"Қасым хан","ru":"Касым хан"}'::jsonb, '{"en":"Curated sources place Kasym Khan’s reign in 1511–1521 and describe stronger political influence.","kk":"Іріктелген дереккөздер 1511–1521 жылдарды Қасым ханның билігіне жатқызып, хандықтың саяси ықпалының нығаюын сипаттайды.","ru":"Курированные источники относят 1511–1521 годы к правлению Касым хана и описывают укрепление политического влияния ханства."}'::jsonb, '{"en":"The Khanate consolidated under Kasym Khan.","kk":"Қасым хан тұсында хандық нығайды.","ru":"При Касым хане ханство укрепилось."}'::jsonb, array['e-history-kasym', 'cambridge-kazakh-history']::text[], '{"action":null,"activeLayers":["territories","people","places"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":["kasym-khan-consolidation"],"personIds":["kasym-khan"],"placeIds":["saraishyk","turkistan"],"public":true,"questionId":"kasym-person","sourceClaims":[{"claimsSupported":{"en":"Reign dates and consolidation","kk":"Билік жылдары және хандықтың нығаюы","ru":"Даты правления и укрепление ханства"},"sourceId":"e-history-kasym"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"kasym-khan","storyId":"formation-and-consolidation-kazakh-khanate"}'::jsonb),
  ('formation-and-consolidation-kazakh-khanate:kerei-and-janibek', 'formation-and-consolidation-kazakh-khanate', 1, 1465, 'kazakh-khanate', '{"bearing":-4,"center":[72.5,44.5],"pitch":32,"zoom":4.8}'::jsonb, '{"en":"Kerei and Janibek","kk":"Керей мен Жәнібек","ru":"Керей и Жанибек"}'::jsonb, '{"en":"Sources associate Kerei and Janibek with the formation of a new political polity.","kk":"Дереккөздер Керей мен Жәнібекті жаңа саяси бірлестіктің қалыптасуымен байланыстырады.","ru":"Керей и Жанибек связаны в источниках с формированием нового политического объединения."}'::jsonb, '{"en":"Kerei and Janibek are regarded as founders of the Khanate.","kk":"Керей мен Жәнібек хандықтың негізін қалаушылар деп саналады.","ru":"Керей и Жанибек считаются основателями ханства."}'::jsonb, array['e-history-kazakh-khanate', 'cambridge-kazakh-history']::text[], '{"action":null,"activeLayers":["territories","people","places"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":["formation-kazakh-khanate"],"personIds":["kerei-khan","janibek-khan"],"placeIds":["chu-valley"],"public":true,"questionId":null,"sourceClaims":[{"claimsSupported":{"en":"The roles of Kerei and Janibek","kk":"Керей мен Жәнібектің рөлі","ru":"Роль Керея и Жанибека"},"sourceId":"e-history-kazakh-khanate"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"kerei-and-janibek","storyId":"formation-and-consolidation-kazakh-khanate"}'::jsonb),
  ('formation-and-consolidation-kazakh-khanate:move-to-moghulistan', 'formation-and-consolidation-kazakh-khanate', 2, 1465, 'kazakh-khanate', '{"bearing":5,"center":[74,44],"pitch":26,"zoom":4.7}'::jsonb, '{"en":"Movement into Moghulistan","kk":"Моғолстанға көшу","ru":"Переход в Могулистан"}'::jsonb, '{"en":"The existing curated model links the Khanate’s origins to groups led by Kerei and Janibek leaving and settling in Moghulistan.","kk":"Қолданыстағы іріктелген модель хандықтың пайда болуын Керей мен Жәнібек бастаған топтардың бөлініп, Моғолстанда орнығуымен байланыстырады.","ru":"Существующая курированная модель связывает происхождение ханства с уходом групп во главе с Кереем и Жанибеком и их закреплением в Могулистане."}'::jsonb, '{"en":"Groups led by Kerei and Janibek moved into the Moghulistan region.","kk":"Керей мен Жәнібек топтары Моғолстан аймағына көшті.","ru":"Группы Керея и Жанибека переместились в район Могулистана."}'::jsonb, array['e-history-kazakh-khanate', 'cambridge-kazakh-history']::text[], '{"action":null,"activeLayers":["territories","places"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate","moghulistan"],"eventIds":["formation-kazakh-khanate"],"personIds":["kerei-khan","janibek-khan"],"placeIds":["chu-valley"],"public":true,"questionId":null,"sourceClaims":[{"claimsSupported":{"en":"Context of separation and movement","kk":"Бөліну мен көшу мәнмәтіні","ru":"Контекст отделения и перемещения"},"sourceId":"cambridge-kazakh-history"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"move-to-moghulistan","storyId":"formation-and-consolidation-kazakh-khanate"}'::jsonb),
  ('formation-and-consolidation-kazakh-khanate:political-context-before-formation', 'formation-and-consolidation-kazakh-khanate', 0, 1464, 'kazakh-khanate', '{"bearing":0,"center":[70,46],"pitch":26,"zoom":4.2}'::jsonb, '{"en":"Political context before the Khanate","kk":"Хандық құрылғанға дейінгі саяси жағдай","ru":"Политическая ситуация до образования ханства"}'::jsonb, '{"en":"The curated model places the Khanate’s formation in the context of Abu’l-Khayr’s polity and Moghulistan. The contextual geometries require scholarly review.","kk":"Іріктелген модель хандықтың құрылуын Әбілқайыр мемлекеті мен Моғолстан мәнмәтініне орналастырады. Контексттік геометриялар ғылыми тексеруді қажет етеді.","ru":"Курированная модель помещает образование ханства в контекст государства Абулхаира и Могулистана. Контекстные геометрии требуют научной проверки."}'::jsonb, '{"en":"Other political formations existed in the region before the Khanate.","kk":"Хандыққа дейін аймақта басқа саяси бірлестіктер болды.","ru":"До ханства в регионе существовали другие политические объединения."}'::jsonb, array['cambridge-kazakh-history']::text[], '{"action":null,"activeLayers":["territories","labels"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["abulkhair-state","moghulistan"],"eventIds":[],"personIds":[],"placeIds":["chu-valley"],"public":true,"questionId":null,"sourceClaims":[{"claimsSupported":{"en":"Political context of late medieval Central Asia","kk":"Кейінгі ортағасырлық Орталық Азияның саяси мәнмәтіні","ru":"Политический контекст позднесредневековой Центральной Азии"},"sourceId":"cambridge-kazakh-history"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"political-context-before-formation","storyId":"formation-and-consolidation-kazakh-khanate"}'::jsonb),
  ('formation-and-consolidation-kazakh-khanate:sources-and-reconstruction', 'formation-and-consolidation-kazakh-khanate', 8, 1511, 'kazakh-khanate', '{"bearing":0,"center":[67,48],"pitch":18,"zoom":4.05}'::jsonb, '{"en":"Sources and reconstruction","kk":"Дереккөздер және реконструкция","ru":"Источники и реконструкция"}'::jsonb, '{"en":"The national history portal and academic volume support the textual claims. The outline remains an editorial visual reconstruction.","kk":"Ұлттық тарих порталы мен академиялық басылым мәтіндік тұжырымдарды растайды. Контур редакциялық көрнекі реконструкция болып қалады.","ru":"Национальный исторический портал и академическое издание подтверждают текстовые утверждения. Контур остаётся редакционной визуальной реконструкцией."}'::jsonb, '{"en":"The text uses sources; the boundary remains approximate.","kk":"Мәтін дереккөздерге сүйенеді; шекара шамамен берілген.","ru":"Текст опирается на источники; граница остаётся приблизительной."}'::jsonb, array['e-history-kazakh-khanate', 'e-history-kasym', 'cambridge-kazakh-history']::text[], '{"action":null,"activeLayers":["territories","sources"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":["kasym-khan-consolidation"],"personIds":[],"placeIds":[],"public":true,"questionId":"formation-sources","sourceClaims":[{"claimsSupported":{"en":"Formation of the Khanate","kk":"Хандықтың құрылуы","ru":"Образование ханства"},"sourceId":"e-history-kazakh-khanate"},{"claimsSupported":{"en":"Kasym Khan’s reign","kk":"Қасым ханның билігі","ru":"Правление Касым хана"},"sourceId":"e-history-kasym"},{"claimsSupported":{"en":"Academic context","kk":"Академиялық мәнмәтін","ru":"Академический контекст"},"sourceId":"cambridge-kazakh-history"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"sources-and-reconstruction","storyId":"formation-and-consolidation-kazakh-khanate"}'::jsonb),
  ('formation-and-consolidation-kazakh-khanate:summary-question', 'formation-and-consolidation-kazakh-khanate', 9, 1511, 'kazakh-khanate', '{"bearing":0,"center":[68,47],"pitch":20,"zoom":4.1}'::jsonb, '{"en":"Final question","kk":"Қорытынды сұрақ","ru":"Итоговый вопрос"}'::jsonb, '{"en":"Explain the difference between a historical claim, a map reconstruction, and an interpretation of change.","kk":"Тарихи тұжырым, карта реконструкциясы және өзгерісті түсіндіру арасындағы айырманы тұжырымдаңыз.","ru":"Сформулируйте различие между историческим утверждением, реконструкцией карты и интерпретацией изменения."}'::jsonb, '{"en":"Separate source-based facts from approximate outlines and their interpretation.","kk":"Дереккөздегі фактіні шамамен берілген контурдан және оны түсіндіруден ажыратыңыз.","ru":"Отделяйте факт из источника от приблизительного контура и его объяснения."}'::jsonb, array['e-history-kazakh-khanate', 'e-history-kasym', 'cambridge-kazakh-history']::text[], '{"action":null,"activeLayers":["territories"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":["formation-kazakh-khanate","kasym-khan-consolidation"],"personIds":["kerei-khan","janibek-khan","kasym-khan"],"placeIds":["chu-valley","saraishyk"],"public":true,"questionId":"reconstruction-boundaries","sourceClaims":[{"claimsSupported":{"en":"Comparison of historical context","kk":"Тарихи мәнмәтінді салыстыру","ru":"Сопоставление исторического контекста"},"sourceId":"cambridge-kazakh-history"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"summary-question","storyId":"formation-and-consolidation-kazakh-khanate"}'::jsonb),
  ('formation-and-consolidation-kazakh-khanate:why-territory-changed', 'formation-and-consolidation-kazakh-khanate', 7, 1511, 'kazakh-khanate', '{"bearing":0,"center":[67,48],"pitch":26,"zoom":4}'::jsonb, '{"en":"Why the displayed territory changed","kk":"Неліктен көрсетілген аумақ өзгерді","ru":"Почему отображаемая территория изменилась"}'::jsonb, '{"en":"Sources link the period to Kasym Khan’s reign and stronger influence. No exact causal claim is made for every part of the outline.","kk":"Дереккөздер кезеңді Қасым ханның билігі және ықпалдың нығаюымен байланыстырады. Контурдың әр бөлігімен нақты себептік байланыс туралы тұжырым жасалмайды.","ru":"Источники связывают период с правлением Касым хана и укреплением влияния. Точная причинная связь с каждой частью контура не утверждается."}'::jsonb, '{"en":"Sources describe consolidation, while the map shows an interpretive reconstruction.","kk":"Дереккөздер хандықтың нығаюын айтады, ал карта шартты реконструкцияны көрсетеді.","ru":"Источники говорят об укреплении ханства, а карта показывает условную реконструкцию."}'::jsonb, array['e-history-kasym', 'cambridge-kazakh-history']::text[], '{"action":{"changeId":"kazakh-khanate-1465-to-1511","type":"change"},"activeLayers":["territories"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":["kasym-khan-consolidation"],"personIds":["kasym-khan"],"placeIds":["saraishyk"],"public":true,"questionId":null,"sourceClaims":[{"claimsSupported":{"en":"Consolidation under Kasym Khan","kk":"Қасым хан тұсындағы нығаю","ru":"Укрепление при Касым хане"},"sourceId":"e-history-kasym"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"why-territory-changed","storyId":"formation-and-consolidation-kazakh-khanate"}'::jsonb),
  ('historical-evidence:evidence-alternatives', 'historical-evidence', 7, 1511, 'kazakh-khanate', '{"bearing":0,"center":[68.75,47],"pitch":14,"zoom":4.1}'::jsonb, '{"en":"Different scholarly interpretations","kk":"Әртүрлі ғылыми нұсқалар","ru":"Разные научные версии"}'::jsonb, '{"en":"Alternative positions should remain separate and source-linked. The demo structure does not portray a real dispute.","kk":"Балама нұсқаларды бөлек сақтап, олардың дереккөздерімен байланыстыру керек. Demo-құрылым нақты дауды көрсетпейді.","ru":"Альтернативные версии нужно хранить раздельно и связывать с их источниками. Demo-структура не изображает реальный спор."}'::jsonb, '{"en":"Different interpretations should not be merged into one “exact” boundary.","kk":"Әртүрлі нұсқаларды бір «дәл» шекараға біріктіруге болмайды.","ru":"Не следует объединять разные версии в одну «точную» границу."}'::jsonb, array['qhm-p1c-educational-overlay']::text[], '{"action":null,"activeLayers":["politicalTerritories"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":[],"personIds":[],"placeIds":[],"public":true,"questionId":"evidence-boundary-versions","sourceClaims":[{"claimsSupported":{"en":"Evidence is limited to the stated claim","kk":"Дәлел көрсетілген claim-мен шектеледі","ru":"Доказательство ограничено указанным claim"},"sourceId":"qhm-p1c-educational-overlay"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-alternatives","storyId":"historical-evidence"}'::jsonb),
  ('historical-evidence:evidence-archaeology', 'historical-evidence', 3, 1465, 'kazakh-khanate', '{"bearing":0,"center":[67.75,47],"pitch":14,"zoom":4.1}'::jsonb, '{"en":"Archaeological finds","kk":"Археологиялық олжалар","ru":"Археологические находки"}'::jsonb, '{"en":"Archaeological context can support place and activity claims, but needs provenance and method documentation.","kk":"Археологиялық контекст орын мен қызметті растай алады, бірақ шығу тегі мен әдісі туралы есеп қажет.","ru":"Археологический контекст может подтверждать место и деятельность, но требует отчёта о происхождении и методе."}'::jsonb, '{"en":"It matters where and how an object was found.","kk":"Заттың қайда және қалай табылғанын білу маңызды.","ru":"Важно знать, где и как найдён предмет."}'::jsonb, array['britannica-kazakhstan-history']::text[], '{"action":null,"activeLayers":["politicalTerritories"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":[],"personIds":[],"placeIds":[],"public":true,"questionId":"evidence-archaeological-place","sourceClaims":[{"claimsSupported":{"en":"Evidence is limited to the stated claim","kk":"Дәлел көрсетілген claim-мен шектеледі","ru":"Доказательство ограничено указанным claim"},"sourceId":"britannica-kazakhstan-history"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-archaeology","storyId":"historical-evidence"}'::jsonb),
  ('historical-evidence:evidence-archive-maps', 'historical-evidence', 4, 1465, 'kazakh-khanate', '{"bearing":0,"center":[68,47],"pitch":14,"zoom":4.1}'::jsonb, '{"en":"Archive maps","kk":"Архив карталары","ru":"Архивные карты"}'::jsonb, '{"en":"Before display, provenance, date, institution, and rights are checked. Only the project-owned educational diagram is used here.","kk":"Картаны көрсетпес бұрын шығу тегі, күні, мекемесі және құқықтары тексеріледі. Мұнда тек жобаның оқу схемасы қолданылады.","ru":"Перед показом карты проверяют происхождение, дату, учреждение и права. Здесь используется только собственная учебная схема."}'::jsonb, '{"en":"The educational diagram is not an archival original.","kk":"Оқу схемасы архивтік түпнұсқа емес.","ru":"Учебная схема не является архивным оригиналом."}'::jsonb, array['qhm-p1c-educational-overlay']::text[], '{"action":null,"activeLayers":["politicalTerritories","archiveMaps"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":[],"personIds":[],"placeIds":[],"public":true,"questionId":null,"sourceClaims":[{"claimsSupported":{"en":"Evidence is limited to the stated claim","kk":"Дәлел көрсетілген claim-мен шектеледі","ru":"Доказательство ограничено указанным claim"},"sourceId":"qhm-p1c-educational-overlay"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-archive-maps","storyId":"historical-evidence"}'::jsonb),
  ('historical-evidence:evidence-compare-maps', 'historical-evidence', 6, 1511, 'kazakh-khanate', '{"bearing":0,"center":[68.5,47],"pitch":14,"zoom":4.8}'::jsonb, '{"en":"Comparing two maps","kk":"Екі картаны салыстыру","ru":"Сравнение двух карт"}'::jsonb, '{"en":"Swipe reveals differences; alignment is not independent proof.","kk":"Swipe айырмашылықтарды көруге көмектеседі. Сәйкестік дербес дәлел емес.","ru":"Swipe помогает увидеть различия. Совпадение не является самостоятельным доказательством."}'::jsonb, '{"en":"Comparison helps ask questions; it does not automatically prove them.","kk":"Салыстыру сұрақ қоюға көмектеседі, автоматты дәлелдемейді.","ru":"Сравнение помогает задавать вопросы, а не автоматически доказывать."}'::jsonb, array['qhm-p1c-educational-overlay']::text[], '{"action":null,"activeLayers":["politicalTerritories","archiveMaps"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":[],"personIds":[],"placeIds":[],"public":true,"questionId":"evidence-map-alignment","sourceClaims":[{"claimsSupported":{"en":"Evidence is limited to the stated claim","kk":"Дәлел көрсетілген claim-мен шектеледі","ru":"Доказательство ограничено указанным claim"},"sourceId":"qhm-p1c-educational-overlay"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-compare-maps","storyId":"historical-evidence"}'::jsonb),
  ('historical-evidence:evidence-conclusion', 'historical-evidence', 8, 1511, 'kazakh-khanate', '{"bearing":0,"center":[69,47],"pitch":14,"zoom":4.1}'::jsonb, '{"en":"Forming a reasoned conclusion","kk":"Негізделген қорытынды жасау","ru":"Формирование обоснованного вывода"}'::jsonb, '{"en":"Before publication, check the claim, source, date, licence, alternatives, and unknowns.","kk":"Жарияламас бұрын claim, дереккөз, күн, лицензия, баламалар және белгісіз элементтерді тексеріңіз.","ru":"Проверьте claim, источник, дату, лицензию, альтернативы и неизвестные элементы перед публикацией."}'::jsonb, '{"en":"A reasoned conclusion states both evidence and limits.","kk":"Негізделген қорытынды дәлелдер мен шектеулерді бірге көрсетеді.","ru":"Обоснованный вывод показывает и доказательства, и ограничения."}'::jsonb, array['qhm-p1c-educational-overlay']::text[], '{"action":null,"activeLayers":["politicalTerritories"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":[],"personIds":[],"placeIds":[],"public":true,"questionId":"evidence-publication-check","sourceClaims":[{"claimsSupported":{"en":"Evidence is limited to the stated claim","kk":"Дәлел көрсетілген claim-мен шектеледі","ru":"Доказательство ограничено указанным claim"},"sourceId":"qhm-p1c-educational-overlay"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-conclusion","storyId":"historical-evidence"}'::jsonb),
  ('historical-evidence:evidence-geography', 'historical-evidence', 5, 1465, 'kazakh-khanate', '{"bearing":0,"center":[68.25,47],"pitch":14,"zoom":4.1}'::jsonb, '{"en":"Geographic data","kk":"Географиялық деректер","ru":"Географические данные"}'::jsonb, '{"en":"Modern georeferencing helps compare images but does not remove historical uncertainty.","kk":"Заманауи геобайланыс суреттерді салыстыруға көмектеседі, бірақ тарихи белгісіздікті жоймайды.","ru":"Современная геопривязка помогает сравнивать изображения, но не устраняет историческую неопределённость."}'::jsonb, '{"en":"Exact image coordinates do not make a historical outline exact.","kk":"Суреттің дәл координатасы тарихи контурды дәл етпейді.","ru":"Точная координата изображения не делает исторический контур точным."}'::jsonb, array['qhm-p1c-educational-overlay']::text[], '{"action":null,"activeLayers":["politicalTerritories"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":[],"personIds":[],"placeIds":[],"public":true,"questionId":null,"sourceClaims":[{"claimsSupported":{"en":"Evidence is limited to the stated claim","kk":"Дәлел көрсетілген claim-мен шектеледі","ru":"Доказательство ограничено указанным claim"},"sourceId":"qhm-p1c-educational-overlay"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-geography","storyId":"historical-evidence"}'::jsonb),
  ('historical-evidence:evidence-reconstruction', 'historical-evidence', 0, 1465, 'kazakh-khanate', '{"bearing":0,"center":[67,47],"pitch":14,"zoom":4.1}'::jsonb, '{"en":"Why a historical map is a reconstruction","kk":"Неліктен тарихи карта реконструкция болып табылады","ru":"Почему историческая карта является реконструкцией"}'::jsonb, '{"en":"A historical map combines incomplete evidence and editorial decisions; its outlines cannot be treated as absolutely exact.","kk":"Тарихи карта толық емес айғақтар мен редакциялық шешімдерді біріктіреді. Оның контурларын абсолютті дәл деп санауға болмайды.","ru":"Историческая карта объединяет неполные свидетельства и редакционные решения. Её контуры нельзя считать абсолютно точными."}'::jsonb, '{"en":"A map of the past is a reasoned but incomplete model.","kk":"Өткеннің картасы — негізделген, бірақ толық емес модель.","ru":"Карта прошлого — обоснованная, но неполная модель."}'::jsonb, array['qhm-p1c-educational-overlay']::text[], '{"action":null,"activeLayers":["politicalTerritories"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":[],"personIds":[],"placeIds":[],"public":true,"questionId":"evidence-fact-interpretation","sourceClaims":[{"claimsSupported":{"en":"Evidence is limited to the stated claim","kk":"Дәлел көрсетілген claim-мен шектеледі","ru":"Доказательство ограничено указанным claim"},"sourceId":"qhm-p1c-educational-overlay"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-reconstruction","storyId":"historical-evidence"}'::jsonb),
  ('historical-evidence:evidence-source-types', 'historical-evidence', 1, 1465, 'kazakh-khanate', '{"bearing":0,"center":[67.25,47],"pitch":14,"zoom":4.1}'::jsonb, '{"en":"Sources historians use","kk":"Тарихшылар қандай дереккөздерді қолданады","ru":"Какие источники используют историки"}'::jsonb, '{"en":"Written records, archaeology, maps, and scholarship answer different questions.","kk":"Жазба құжаттар, археология, карталар және ғылыми зерттеулер әртүрлі сұрақтарға жауап береді.","ru":"Письменные документы, археология, карты и научные исследования отвечают на разные вопросы."}'::jsonb, '{"en":"Each source has strengths and limits.","kk":"Әр дереккөздің мүмкіндігі мен шектеуі бар.","ru":"У каждого источника есть свои возможности и ограничения."}'::jsonb, array['adilet-independence-law', 'britannica-kazakhstan-history']::text[], '{"action":null,"activeLayers":["politicalTerritories"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":[],"personIds":[],"placeIds":[],"public":true,"questionId":null,"sourceClaims":[{"claimsSupported":{"en":"Evidence is limited to the stated claim","kk":"Дәлел көрсетілген claim-мен шектеледі","ru":"Доказательство ограничено указанным claim"},"sourceId":"adilet-independence-law"},{"claimsSupported":{"en":"Evidence is limited to the stated claim","kk":"Дәлел көрсетілген claim-мен шектеледі","ru":"Доказательство ограничено указанным claim"},"sourceId":"britannica-kazakhstan-history"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-source-types","storyId":"historical-evidence"}'::jsonb),
  ('historical-evidence:evidence-written', 'historical-evidence', 2, 1465, 'kazakh-khanate', '{"bearing":0,"center":[67.5,47],"pitch":14,"zoom":4.1}'::jsonb, '{"en":"Written sources","kk":"Жазба дереккөздер","ru":"Письменные источники"}'::jsonb, '{"en":"An official law directly records a legal event date, but does not establish medieval geometry.","kk":"Ресми заң құқықтық оқиғаның күнін тікелей бекітеді, бірақ ортағасырлық геометрияны растамайды.","ru":"Официальный закон прямо фиксирует дату правового события, но не подтверждает средневековую геометрию."}'::jsonb, '{"en":"A source supports only what it actually addresses.","kk":"Дереккөз тек өзінде айтылғанды растайды.","ru":"Источник подтверждает только то, о чём в нём говорится."}'::jsonb, array['adilet-independence-law']::text[], '{"action":null,"activeLayers":["politicalTerritories"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["kazakh-khanate"],"eventIds":["formation-kazakh-khanate"],"personIds":[],"placeIds":[],"public":true,"questionId":"evidence-fact-interpretation","sourceClaims":[{"claimsSupported":{"en":"Evidence is limited to the stated claim","kk":"Дәлел көрсетілген claim-мен шектеледі","ru":"Доказательство ограничено указанным claim"},"sourceId":"adilet-independence-law"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-written","storyId":"historical-evidence"}'::jsonb),
  ('silk-road-geography:central-asia-position', 'silk-road-geography', 0, 900, 'turkic', '{"bearing":0,"center":[68,44],"pitch":16,"zoom":3.8}'::jsonb, '{"en":"The geographic position of Central Asia","kk":"Орталық Азияның географиялық орны","ru":"Географическое положение Центральной Азии"}'::jsonb, '{"en":"Central Asia connects steppe, mountain, and river landscapes. Routes on the map are shown as reconstructions.","kk":"Орталық Азия дала, тау және өзен кеңістіктерін байланыстырады. Картадағы бағыттар реконструкция ретінде көрсетілген.","ru":"Центральная Азия соединяет степные, горные и речные пространства. Маршруты на карте показаны как реконструкция."}'::jsonb, '{"en":"Different environments meet within one large region.","kk":"Бір үлкен аймақта әртүрлі табиғи аймақтар кездеседі.","ru":"Разные природные зоны встречаются в одном большом регионе."}'::jsonb, array['unesco-silk-roads']::text[], '{"action":null,"activeLayers":["politicalTerritories","environment","tradeRoutes"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":["first-turkic-khaganate"],"eventIds":[],"personIds":[],"placeIds":[],"public":true,"questionId":"geography-route-reconstruction","sourceClaims":[{"claimsSupported":{"en":"Broader context of the Silk Roads network","kk":"Жібек жолдары желісінің жалпы мәнмәтіні","ru":"Общий контекст сети Шёлковых путей"},"sourceId":"unesco-silk-roads"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"central-asia-position","storyId":"silk-road-geography"}'::jsonb),
  ('silk-road-geography:geography-summary', 'silk-road-geography', 7, 1200, 'turkic', '{"bearing":0,"center":[68.8,43.2],"pitch":15,"zoom":4.5}'::jsonb, '{"en":"How geography supported trade and cultural exchange","kk":"География сауда мен мәдени алмасуды қалай қолдады","ru":"Как география поддерживала торговлю и культурный обмен"}'::jsonb, '{"en":"Natural corridors and a network of urban centres supported connections. This map does not quantify the intensity of exchange.","kk":"Табиғи дәліздер мен қала орталықтарының желісі байланыстарға жағдай жасады. Бұл карта алмасудың нақты қарқынын өлшемейді.","ru":"Природные коридоры и сеть городских центров создавали условия для связей. Точная интенсивность обмена этой картой не измеряется."}'::jsonb, '{"en":"Environment and cities together helped connect regions.","kk":"Табиғат пен қалалар аймақтарды байланыстыруға бірге көмектесті.","ru":"Природа и города вместе помогали связывать регионы."}'::jsonb, array['unesco-silk-roads', 'cambridge-kazakh-history']::text[], '{"action":null,"activeLayers":["historicalPlaces","tradeRoutes","environment"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":[],"eventIds":[],"personIds":[],"placeIds":["taraz","sayram","otrar","turkistan","syganak"],"public":true,"questionId":"geography-route-reconstruction","sourceClaims":[{"claimsSupported":{"en":"Links between historic centres and cultural exchange","kk":"Тарихи орталықтар мен мәдени алмасудың байланысы","ru":"Связь исторических центров и культурного обмена"},"sourceId":"unesco-silk-roads"},{"claimsSupported":{"en":"Historical context of the region’s political formations","kk":"Аймақтың саяси құрылымдарының тарихи мәнмәтіні","ru":"Исторический контекст политических образований региона"},"sourceId":"cambridge-kazakh-history"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"geography-summary","storyId":"silk-road-geography"}'::jsonb),
  ('silk-road-geography:otrar-geography', 'silk-road-geography', 5, 1200, 'turkic', '{"bearing":0,"center":[68.3,42.85],"pitch":22,"zoom":6.2}'::jsonb, '{"en":"Otrar","kk":"Отырар","ru":"Отырар"}'::jsonb, '{"en":"Otrar is shown as a historic urban centre near the reconstructed route direction.","kk":"Отырар реконструкцияланған бағытқа жақын тарихи қала орталығы ретінде көрсетілген.","ru":"Отырар показан как исторический городской центр рядом с реконструированным направлением маршрута."}'::jsonb, '{"en":"The city formed part of a network of historic centres.","kk":"Қала тарихи орталықтар желісінің бөлігі болды.","ru":"Город был частью сети исторических центров."}'::jsonb, array['unesco-silk-roads']::text[], '{"action":null,"activeLayers":["historicalPlaces","archaeology","tradeRoutes","environment"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":[],"eventIds":[],"personIds":[],"placeIds":["otrar"],"public":true,"questionId":"geography-cultural-links","sourceClaims":[{"claimsSupported":{"en":"The city within the broader route network","kk":"Қаланың жалпы жолдар желісіндегі орны","ru":"Город как часть общей сети путей"},"sourceId":"unesco-silk-roads"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"otrar-geography","storyId":"silk-road-geography"}'::jsonb),
  ('silk-road-geography:sayram-geography', 'silk-road-geography', 4, 1100, 'turkic', '{"bearing":0,"center":[69.76,42.3],"pitch":22,"zoom":6.2}'::jsonb, '{"en":"Sayram","kk":"Сайрам","ru":"Сайрам"}'::jsonb, '{"en":"Sayram is shown as a historic urban centre near the reconstructed route direction.","kk":"Сайрам реконструкцияланған бағытқа жақын тарихи қала орталығы ретінде көрсетілген.","ru":"Сайрам показан как исторический городской центр рядом с реконструированным направлением маршрута."}'::jsonb, '{"en":"The city formed part of a network of historic centres.","kk":"Қала тарихи орталықтар желісінің бөлігі болды.","ru":"Город был частью сети исторических центров."}'::jsonb, array['unesco-silk-roads']::text[], '{"action":null,"activeLayers":["historicalPlaces","archaeology","tradeRoutes","environment"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":[],"eventIds":[],"personIds":[],"placeIds":["sayram"],"public":true,"questionId":null,"sourceClaims":[{"claimsSupported":{"en":"The city within the broader route network","kk":"Қаланың жалпы жолдар желісіндегі орны","ru":"Город как часть общей сети путей"},"sourceId":"unesco-silk-roads"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"sayram-geography","storyId":"silk-road-geography"}'::jsonb),
  ('silk-road-geography:steppe-mountains-valleys', 'silk-road-geography', 1, 900, 'turkic', '{"bearing":0,"center":[72,42.5],"pitch":20,"zoom":4.2}'::jsonb, '{"en":"Steppe, mountains, and river valleys","kk":"Дала, таулар және өзен аңғарлары","ru":"Степь, горы и речные долины"}'::jsonb, '{"en":"Natural zones influenced access to water and possible movement corridors, but the demonstration outlines require review.","kk":"Табиғи аймақтар суға қолжетімділік пен қозғалыс бағыттарына әсер етті, бірақ демонстрациялық контурлар тексеруді қажет етеді.","ru":"Природные зоны влияли на доступ к воде и возможные направления движения, но демонстрационные контуры требуют проверки."}'::jsonb, '{"en":"Water and terrain influenced route choices.","kk":"Су мен жер бедері жол таңдауға әсер етті.","ru":"Вода и рельеф влияли на выбор пути."}'::jsonb, array['unesco-silk-roads']::text[], '{"action":null,"activeLayers":["environment","hydrology","tradeRoutes"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":[],"eventIds":[],"personIds":[],"placeIds":[],"public":true,"questionId":"geography-caravan-conditions","sourceClaims":[{"claimsSupported":{"en":"Relationship between routes and geographic context","kk":"Бағыттар мен табиғи-географиялық мәнмәтіннің байланысы","ru":"Связь маршрутов и природно-географического контекста"},"sourceId":"unesco-silk-roads"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"steppe-mountains-valleys","storyId":"silk-road-geography"}'::jsonb),
  ('silk-road-geography:taraz-geography', 'silk-road-geography', 3, 1000, 'turkic', '{"bearing":0,"center":[71.37,42.9],"pitch":22,"zoom":6.2}'::jsonb, '{"en":"Taraz","kk":"Тараз","ru":"Тараз"}'::jsonb, '{"en":"Taraz is shown as a historic urban centre near the reconstructed route direction.","kk":"Тараз реконструкцияланған бағытқа жақын тарихи қала орталығы ретінде көрсетілген.","ru":"Тараз показан как исторический городской центр рядом с реконструированным направлением маршрута."}'::jsonb, '{"en":"The city formed part of a network of historic centres.","kk":"Қала тарихи орталықтар желісінің бөлігі болды.","ru":"Город был частью сети исторических центров."}'::jsonb, array['unesco-silk-roads']::text[], '{"action":null,"activeLayers":["historicalPlaces","archaeology","tradeRoutes","environment"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":[],"eventIds":[],"personIds":[],"placeIds":["taraz"],"public":true,"questionId":"geography-river-cities","sourceClaims":[{"claimsSupported":{"en":"The city within the broader route network","kk":"Қаланың жалпы жолдар желісіндегі орны","ru":"Город как часть общей сети путей"},"sourceId":"unesco-silk-roads"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"taraz-geography","storyId":"silk-road-geography"}'::jsonb),
  ('silk-road-geography:turkistan-syganak-geography', 'silk-road-geography', 6, 1300, 'turkic', '{"bearing":0,"center":[68.25,43.3],"pitch":22,"zoom":6.2}'::jsonb, '{"en":"Turkistan and Syganak","kk":"Түркістан және Сығанақ","ru":"Туркестан и Сыганак"}'::jsonb, '{"en":"Turkistan and Syganak is shown as a historic urban centre near the reconstructed route direction.","kk":"Түркістан және Сығанақ реконструкцияланған бағытқа жақын тарихи қала орталығы ретінде көрсетілген.","ru":"Туркестан и Сыганак показан как исторический городской центр рядом с реконструированным направлением маршрута."}'::jsonb, '{"en":"The city formed part of a network of historic centres.","kk":"Қала тарихи орталықтар желісінің бөлігі болды.","ru":"Город был частью сети исторических центров."}'::jsonb, array['unesco-silk-roads']::text[], '{"action":null,"activeLayers":["historicalPlaces","archaeology","tradeRoutes","environment"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":[],"eventIds":[],"personIds":[],"placeIds":["turkistan"],"public":true,"questionId":null,"sourceClaims":[{"claimsSupported":{"en":"The city within the broader route network","kk":"Қаланың жалпы жолдар желісіндегі орны","ru":"Город как часть общей сети путей"},"sourceId":"unesco-silk-roads"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"turkistan-syganak-geography","storyId":"silk-road-geography"}'::jsonb),
  ('silk-road-geography:why-southern-kazakhstan', 'silk-road-geography', 2, 900, 'turkic', '{"bearing":0,"center":[69.5,42.8],"pitch":18,"zoom":5}'::jsonb, '{"en":"Why routes crossed southern Kazakhstan","kk":"Неліктен бағыттар Оңтүстік Қазақстан арқылы өтті","ru":"Почему маршруты проходили через Южный Казахстан"}'::jsonb, '{"en":"The educational model compares urban centres, valleys, and a reconstructed direction without asserting one exact path.","kk":"Оқу моделі бір дәл жолды мәлімдемей, қала орталықтарын, аңғарларды және реконструкцияланған бағытты салыстырады.","ru":"Учебная модель сопоставляет городские центры, долины и реконструированное направление, не утверждая единственный точный путь."}'::jsonb, '{"en":"Cities and accessible natural corridors formed a network.","kk":"Қалалар мен қолжетімді табиғи дәліздер желі құрды.","ru":"Города и доступные природные коридоры образовывали сеть."}'::jsonb, array['unesco-silk-roads']::text[], '{"action":null,"activeLayers":["environment","historicalPlaces","tradeRoutes"],"datasetVersion":"p2a-2026-08","durationMs":60000,"entityIds":[],"eventIds":[],"personIds":[],"placeIds":["sayram","taraz","otrar"],"public":true,"questionId":null,"sourceClaims":[{"claimsSupported":{"en":"Southern Kazakhstan context of the historic-centre network","kk":"Тарихи орталықтар желісінің Оңтүстік Қазақстан мәнмәтіні","ru":"Южноказахстанский контекст сети исторических центров"},"sourceId":"unesco-silk-roads"}],"sourceDataset":"src/data/exhibition/stories.js","sourceId":"why-southern-kazakhstan","storyId":"silk-road-geography"}'::jsonb)
