values
  ('compare-1465-1511', 'formation-and-consolidation-kazakh-khanate', 'compare', '[object Object]', '[{"id":"a","label":{"en":"The 1511 outline has a broader displayed extent","kk":"1511 жылғы контурдың көрсетілген қамтуы үлкен","ru":"Контур 1511 года имеет больший отображаемый охват"}},{"id":"b","label":{"en":"Both geometries disappear entirely","kk":"Екі геометрия да толық жоғалады","ru":"Обе геометрии полностью исчезают"}},{"id":"c","label":{"en":"The map proves exact borders","kk":"Карта дәл шекараларды дәлелдейді","ru":"Карта доказывает точные границы"}}]'::jsonb, '{"correctOptionId":"a"}'::jsonb, '{"en":"The visual extent increases, but the difference between reconstructions is not independent historical evidence.","kk":"Көрнекі қамту ұлғаяды, бірақ реконструкциялар айырмасы жеке тарихи дәлел емес.","ru":"Визуальный охват увеличивается, но разница реконструкций не является самостоятельным историческим доказательством."}'::jsonb, array['e-history-kasym', 'cambridge-kazakh-history']::text[], 'needs_review', '{"accessiblePrompts":{},"datasetVersion":"p2a-2026-08","evidenceType":null,"public":true,"sourceDataset":"src/data/exhibition/stories.js","sourceId":"compare-1465-1511","statusWasMissing":true}'::jsonb),
  ('evidence-archaeological-place', 'historical-evidence', 'evidence-selection', '[object Object]', '[{"id":"a","label":{"en":"An archaeological report documenting find provenance","kk":"Олжалардың шығу тегі көрсетілген археологиялық есеп","ru":"Археологический отчёт с происхождением находок"}},{"id":"b","label":{"en":"An unrelated modern route","kk":"Қатысы жоқ заманауи бағыт","ru":"Несвязанный современный маршрут"}},{"id":"c","label":{"en":"An unattributed image","kk":"Атрибуциясыз сурет","ru":"Неатрибутированная картинка"}}]'::jsonb, '{"correctOptionId":"a"}'::jsonb, '{"en":"Archaeological claims require find context, method, and publication.","kk":"Археологиялық тұжырым үшін олжаның контексті, әдісі және жарияланымы маңызды.","ru":"Для археологического утверждения важны контекст находки, метод и публикация."}'::jsonb, array['britannica-kazakhstan-history']::text[], 'reviewed', '{"accessiblePrompts":{"en":"Choose the most direct evidence type.","kk":"Ең тікелей дәлел түрін таңдаңыз.","ru":"Выберите наиболее прямой тип доказательства."},"datasetVersion":"p2a-2026-08","evidenceType":"archaeological_evidence","public":true,"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-archaeological-place","statusWasMissing":false}'::jsonb),
  ('evidence-boundary-versions', 'historical-evidence', 'source-analysis', '[object Object]', '[{"id":"a","label":{"en":"Sources can reflect different periods, concepts of territory, and completeness","kk":"Дереккөздер әр кезеңді, аумақ ұғымын және толықтық деңгейін көрсетеді","ru":"Источники отражают разные периоды, понятия территории и степень полноты"}},{"id":"b","label":{"en":"One map must be fraudulent","kk":"Бір карта міндетті түрде жалған","ru":"Одна карта обязательно является подделкой"}},{"id":"c","label":{"en":"Polygon colour determines truth","kk":"Полигон түсі ақиқатты анықтайды","ru":"Цвет полигона определяет истину"}}]'::jsonb, '{"correctOptionId":"a"}'::jsonb, '{"en":"Reconstructions need period, method, and a statement of what the outline represents.","kk":"Реконструкция кезеңді, әдісті және контур нені білдіретінін сипаттауды қажет етеді.","ru":"Реконструкции требуют описания периода, метода и того, что именно означает контур."}'::jsonb, array['cambridge-kazakh-history', 'qhm-p1c-educational-overlay']::text[], 'reviewed', '{"accessiblePrompts":{"en":"Choose why reconstructions can differ.","kk":"Реконструкциялар айырмасының түсіндірмесін таңдаңыз.","ru":"Выберите объяснение различий реконструкций."},"datasetVersion":"p2a-2026-08","evidenceType":"academic_interpretation","public":true,"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-boundary-versions","statusWasMissing":false}'::jsonb),
  ('evidence-fact-interpretation', 'historical-evidence', 'classify', '[object Object]', '[{"id":"a","label":{"en":"A fact is directly tied to cited evidence; an interpretation explains its meaning","kk":"Факт көрсетілген айғақпен тікелей байланысты; түсіндіру оның мағынасын ашады","ru":"Факт прямо связан с указанным свидетельством; интерпретация объясняет его значение"}},{"id":"b","label":{"en":"There is no difference","kk":"Олардың айырмашылығы жоқ","ru":"Между ними нет различия"}},{"id":"c","label":{"en":"An interpretation is always more exact than its source","kk":"Түсіндіру әрқашан дереккөзден дәлірек","ru":"Интерпретация всегда точнее источника"}}]'::jsonb, '{"correctOptionId":"a"}'::jsonb, '{"en":"A claim records what a source supports; interpretation must be labelled separately.","kk":"Claim дереккөз нені растайтынын көрсетеді, ал түсіндіру бөлек белгіленуі тиіс.","ru":"Claim показывает, что именно подтверждает источник, а интерпретация должна быть обозначена отдельно."}'::jsonb, array['adilet-independence-law', 'qhm-p1c-educational-overlay']::text[], 'reviewed', '{"accessiblePrompts":{"en":"Classify fact and interpretation.","kk":"Факт пен түсіндіруді жіктеңіз.","ru":"Классифицируйте факт и интерпретацию."},"datasetVersion":"p2a-2026-08","evidenceType":"source-analysis","public":true,"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-fact-interpretation","statusWasMissing":false}'::jsonb),
  ('evidence-map-alignment', 'historical-evidence', 'compare', '[object Object]', '[{"id":"a","label":{"en":"No; it supports analysis but is not independent proof","kk":"Жоқ, бұл талдауға себеп, бірақ дербес дәлел емес","ru":"Нет, это повод для анализа, но не самостоятельное доказательство"}},{"id":"b","label":{"en":"Yes; any alignment proves accuracy","kk":"Иә, кез келген сәйкестік дәлдікті растайды","ru":"Да, любое совпадение доказывает точность"}},{"id":"c","label":{"en":"Opacity automatically validates a source","kk":"Мөлдірлік дереккөзді автоматты тексереді","ru":"Прозрачность автоматически проверяет источник"}}]'::jsonb, '{"correctOptionId":"a"}'::jsonb, '{"en":"Provenance, date, scale, georeferencing, and purpose of both maps must be considered.","kk":"Екі картаның шығу тегі, күні, масштабы, геобайланысы және мақсаты ескерілуі керек.","ru":"Нужно учитывать происхождение, дату, масштаб, геопривязку и цель обеих карт."}'::jsonb, array['qhm-p1c-educational-overlay']::text[], 'reviewed', '{"accessiblePrompts":{"en":"Assess the meaning of visual alignment.","kk":"Көрнекі сәйкестіктің маңызын бағалаңыз.","ru":"Оцените значение визуального совпадения."},"datasetVersion":"p2a-2026-08","evidenceType":"historical_map","public":true,"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-map-alignment","statusWasMissing":false}'::jsonb),
  ('evidence-publication-check', 'historical-evidence', 'single-choice', '[object Object]', '[{"id":"a","label":{"en":"Sources, claims, dates, licences, translations, and review status","kk":"Дереккөздер, claims, күндер, лицензиялар, аудармалар және тексеру мәртебесі","ru":"Источники, claims, даты, лицензии, переводы и статус проверки"}},{"id":"b","label":{"en":"Only map colour","kk":"Тек карта түсі","ru":"Только цвет карты"}},{"id":"c","label":{"en":"Only file size","kk":"Тек файл өлшемі","ru":"Только размер файла"}}]'::jsonb, '{"correctOptionId":"a"}'::jsonb, '{"en":"Publication requires content, provenance, and rights review.","kk":"Жариялау мазмұнды, шығу тегін және пайдалану құқықтарын тексеруді талап етеді.","ru":"Публикация требует проверки содержания, происхождения и прав использования."}'::jsonb, array['qhm-p1c-educational-overlay']::text[], 'reviewed', '{"accessiblePrompts":{"en":"Choose the complete editorial check.","kk":"Редакциялық тексерулердің толық жиынын таңдаңыз.","ru":"Выберите полный набор редакционных проверок."},"datasetVersion":"p2a-2026-08","evidenceType":"official_document","public":true,"sourceDataset":"src/data/exhibition/stories.js","sourceId":"evidence-publication-check","statusWasMissing":false}'::jsonb),
