  ('geography-caravan-conditions', 'silk-road-geography', 'compare', '[object Object]', '[{"id":"a","label":{"en":"Access to water and passable valleys","kk":"Суға қолжетімділік және өтетін аңғарлар","ru":"Доступ к воде и проходимые долины"}},{"id":"b","label":{"en":"Only modern motorways","kk":"Тек заманауи автожолдар","ru":"Только современные автомагистрали"}},{"id":"c","label":{"en":"Absence of any stops","kk":"Ешқандай аялдаманың болмауы","ru":"Отсутствие любых остановок"}}]'::jsonb, '{"correctOptionId":"a"}'::jsonb, '{"en":"River valleys and access to water could support movement; the exact path remains reconstructed.","kk":"Өзен аңғарлары мен суға қолжетімділік қозғалысқа көмектесе алды; нақты жол реконструкция болып қалады.","ru":"Речные долины и доступ к воде могли поддерживать движение; точный путь остаётся реконструкцией."}'::jsonb, array['unesco-silk-roads']::text[], 'reviewed', '{"accessiblePrompts":{"en":"Compare the route’s natural conditions.","kk":"Бағыттың табиғи жағдайларын салыстырыңыз.","ru":"Сравните природные условия маршрута."},"datasetVersion":"p2a-2026-08","evidenceType":null,"public":true,"sourceDataset":"src/data/exhibition/stories.js","sourceId":"geography-caravan-conditions","statusWasMissing":false}'::jsonb),
  ('geography-cultural-links', 'silk-road-geography', 'map-selection', '[object Object]', '[{"id":"a","label":{"en":"Through encounters and exchange of ideas in urban centres","kk":"Қала орталықтарында адамдардың кездесуі және идея алмасуы арқылы","ru":"Через встречи людей и обмен идеями в городских центрах"}},{"id":"b","label":{"en":"By isolating every city","kk":"Әр қаланы оқшаулау арқылы","ru":"Изолируя каждый город"}},{"id":"c","label":{"en":"Only by changing borders on a map","kk":"Тек картадағы шекараларды өзгерту арқылы","ru":"Только меняя границы на карте"}}]'::jsonb, '{"correctOptionId":"a"}'::jsonb, '{"en":"The network connected centres where contacts occurred; the map does not quantify that exchange.","kk":"Жолдар желісі байланыс орын алған орталықтарды қосты; карта алмасу көлемін өлшемейді.","ru":"Сеть путей соединяла центры, где происходили контакты; карта не измеряет объём обмена."}'::jsonb, array['unesco-silk-roads', 'cambridge-kazakh-history']::text[], 'reviewed', '{"accessiblePrompts":{"en":"Choose the role of the network of historic cities.","kk":"Тарихи қалалар желісінің рөлін таңдаңыз.","ru":"Выберите роль сети исторических городов."},"datasetVersion":"p2a-2026-08","evidenceType":null,"public":true,"sourceDataset":"src/data/exhibition/stories.js","sourceId":"geography-cultural-links","statusWasMissing":false}'::jsonb),
  ('geography-river-cities', 'silk-road-geography', 'single-choice', '[object Object]', '[{"id":"a","label":{"en":"Water and routes supported settlement and exchange","kk":"Су мен жолдар қоныстану мен алмасуға көмектесті","ru":"Вода и пути поддерживали поселение и обмен"}},{"id":"b","label":{"en":"Rivers had no relationship to cities","kk":"Өзендердің қалаларға қатысы болмады","ru":"Реки не имели отношения к городам"}},{"id":"c","label":{"en":"All cities appeared at the same time","kk":"Барлық қалалар бір уақытта пайда болды","ru":"Все города возникли одновременно"}}]'::jsonb, '{"correctOptionId":"a"}'::jsonb, '{"en":"Water and accessible movement corridors supported life and exchange, although their role varied by period.","kk":"Су мен қолжетімді қозғалыс бағыттары өмір мен алмасуға жағдай жасады, бірақ олардың рөлі кезеңге қарай өзгерді.","ru":"Вода и доступные направления движения создавали условия для жизни и обмена, но их роль различалась по периодам."}'::jsonb, array['unesco-silk-roads']::text[], 'reviewed', '{"accessiblePrompts":{"en":"Choose an explanation connecting water, routes, and cities.","kk":"Су, жол және қала байланысын түсіндіретін жауапты таңдаңыз.","ru":"Выберите объяснение связи воды, путей и городов."},"datasetVersion":"p2a-2026-08","evidenceType":null,"public":true,"sourceDataset":"src/data/exhibition/stories.js","sourceId":"geography-river-cities","statusWasMissing":false}'::jsonb),
